  $('now').textContent = (tomorrow?'Wednesday · ':'Tuesday · ') + fmt(clockMin) + ' · ' + (tomorrow?'51° clear':weather(clockMin));
  var dayF = cl((Math.min(smin,1410)-420)/(1410-420));
  $('knob').style.transform = 'translate3d('+(dayF*$('rail').offsetWidth).toFixed(1)+'px,0,0)';
